import React, { useEffect, useState } from 'react';
import Loading from '../../loading/Loading';
import CompanyMenu from '../Company_Menu/CompanyMenu';
import './CompanyOrders.css';

const CompanyOrders = () => {
    const [loading, setLoading] = useState(true);
    const [orders, setOrders] = useState([]);
    const [formData, setFormData] = useState({
        color: '',
        talla: '',
        costo: '',
        marca: '',
        modelo: '',
        descripcion: '',
        calidad: '',
        url: '',
        cantidad: 1,
        total: 0
    });

    useEffect(() => {
        const timer = setTimeout(() => {
            setLoading(false);
        }, 3000);

        return () => clearTimeout(timer);
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData({ ...formData, url: reader.result });
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const newOrder = { ...formData, id: Date.now(), total: formData.costo * formData.cantidad };
        setOrders([...orders, newOrder]);
        setFormData({
            color: '',
            talla: '',
            costo: '',
            marca: '',
            modelo: '',
            descripcion: '',
            calidad: '',
            url: '',
            cantidad: 1,
            total: 0
        });
    };

    const handleDelete = (id) => {
        setOrders(orders.filter(order => order.id !== id));
    };

    const handleUpdate = (id) => {
        const order = orders.find(order => order.id === id);
        setFormData(order);
        setOrders(orders.filter(order => order.id !== id));
    };

    return (
        <div>
            {loading ? <Loading /> : null}
            <CompanyMenu className="nav-menu" />
            <div className="body-orders">
                <h2>Registrar Nueva Venta</h2>
                <form className="form-orders" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Color:</label>
                        <input 
                            type="text" 
                            name="color" 
                            value={formData.color} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Talla:</label>
                        <input 
                            type="text" 
                            name="talla" 
                            value={formData.talla} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Costo:</label>
                        <input 
                            type="number" 
                            name="costo" 
                            value={formData.costo} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Marca:</label>
                        <input 
                            type="text" 
                            name="marca" 
                            value={formData.marca} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Modelo:</label>
                        <input 
                            type="text" 
                            name="modelo" 
                            value={formData.modelo} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Calidad:</label>
                        <select 
                            name="calidad" 
                            value={formData.calidad} 
                            onChange={handleChange} 
                        >
                            <option value="">Seleccione</option>
                            <option value="AA">AA</option>
                            <option value="AAA">AAA</option>
                            <option value="Tipo Original">Tipo Original</option>
                            <option value="Original">Original</option>
                        </select>
                    </div>
                    <div className="form-group form-group-textarea">
                        <label>Descripción:</label>
                        <textarea 
                            name="descripcion" 
                            value={formData.descripcion} 
                            onChange={handleChange} 
                            style={{ height: '50px' }}
                        ></textarea>
                    </div>
                    <div className="form-group">
                        <label>Cantidad:</label>
                        <input 
                            type="number" 
                            name="cantidad" 
                            value={formData.cantidad} 
                            onChange={handleChange} 
                            min="1"
                        />
                    </div>
                    <div className="form-group">
                        <label>Subir Imagen:</label>
                        <input 
                            type="file" 
                            accept="image/*" 
                            onChange={handleFileChange} 
                        />
                    </div>
                    {formData.url && (
                        <div className="form-group">
                            <label>Vista Previa:</label>
                            <img src={formData.url} alt="Vista previa" className="img-preview" />
                        </div>
                    )}
                    <button type="submit">Guardar Venta</button>
                </form>
                <h2>Lista de Ventas</h2>
                <ul className="order-list">
                    {orders.map(order => (
                        <li key={order.id} className="order-item">
                            <div className="order-details">
                                <p><strong>Color:</strong> {order.color}</p>
                                <p><strong>Talla:</strong> {order.talla}</p>
                                <p><strong>Costo:</strong> ${order.costo}</p>
                                <p><strong>Marca:</strong> {order.marca}</p>
                                <p><strong>Modelo:</strong> {order.modelo}</p>
                                <p><strong>Calidad:</strong> {order.calidad}</p>
                                <p><strong>Descripción:</strong> {order.descripcion}</p>
                                <p><strong>Cantidad:</strong> {order.cantidad}</p>
                                <p><strong>Total:</strong> ${order.total}</p>
                                {order.url && <img src={order.url} alt="Producto" className="order-img" />}
                            </div>
                            <div className="order-actions">
                                <button onClick={() => handleUpdate(order.id)}>Actualizar</button>
                                <button onClick={() => handleDelete(order.id)}>Eliminar</button>
                            </div>
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
};

export default CompanyOrders;
